// 📋 CALLBACK MAYAR — format resmi dari docs (docs.mayar.id/integration/webhook)
// Event: payment.received (setelah customer selesai bayar)
// Payload:
//   data.customerName, data.customerEmail, data.customerMobile
//   data.amount, data.status, data.transactionStatus, data.productId, data.productName
//   data.pixelFbp, data.pixelFbc (cookie Meta Pixel — buat CAPI dedup)

const raw = $input.first().json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;

const event = body.event || body['event.received'] || '';
const data = body.data || {};

// Status transaksi. Docs bilang Boolean, tapi riwayat riil Mayar mengirim
// string "SUCCESS" — terima keduanya supaya tidak diam-diam lolos.
const s = data.status;
const statusPaid = s === true || s === 'true' || s === 'PAID' || s === 'paid' ||
                   s === 'SUCCESS' || s === 'success';
const txPaid = data.transactionStatus === 'paid' || data.transactionStatus === 'PAID';

// Event payment.received = pembayaran selesai
const isPaymentReceived = event === 'payment.received' || event === 'PAID' || statusPaid || txPaid;

return {
  json: {
    valid: true,
    event: event,
    isPaid: isPaymentReceived,
    reference: data.transactionId || data.id || body.id || '',
    amount: Number(data.amount || 0),
    customerName: data.customerName || '',
    customerEmail: data.customerEmail || '',
    customerMobile: data.customerMobile || '',
    productId: data.productId || '',
    productName: data.productName || '',
    pixelFbp: data.pixelFbp || '',
    pixelFbc: data.pixelFbc || '',
    raw: JSON.stringify(raw).slice(0, 2000)
  }
};

// Tier ditentukan dari productId (kenaan), BUKUM dari nama produk.
// Nama produk aslinya "Langganan Life-Time" — contains('lifetime') = false,
// sehingga pembeli Life-Time dulu salah provisioned jadi 'yearly'.
const TIER_BY_PRODUCT_ID = {
  'd8927ccd-4323-4500-b4f3-2f0e4f82acd1': 'yearly',   // Langganan 1 Tahun (Rp 599.000)
  '56284414-f48b-47b9-af79-74d2b0f4b2dd': 'lifetime'  // Langganan Life-Time (Rp 999.000)
};

const p = $input.first().json;

let tier = TIER_BY_PRODUCT_ID[String(p.productId || '').toLowerCase()];
if (!tier) {
  const txt = [p.productName || '', p.raw || ''].join(' ').toLowerCase();
  tier = /life[\s-]?time|lifetime/.test(txt) ? 'lifetime' : 'yearly';
}

return {
  json: {
    email: p.customerEmail || '',
    name: p.customerName || '',
    mobile: p.customerMobile || '',
    tier: tier,
    amount: p.amount || 0,
    reference: p.reference || '',
    tierSource: TIER_BY_PRODUCT_ID[String(p.productId || '').toLowerCase()] ? 'productId' : 'productName'
  }
};

// \u2728 EMAIL AKSES \u2014 dikirim via Resend setelah /api/provision-lms mengembalikan kredensial.
// Token node ini berisi respons API, BUKAN payload Mayar \u2014 jadi nama/email harus
// diambil dari node Parse, password dari respons provisioning.
const parsed = $('Code: Parse Mayar Callback').first().json;
const prep = $('Code: Siapkan Data LMS').first().json;
const prov = $input.first().json || {};

const RESEND_FROM = $env.RESEND_FROM || 'XindeLabs <no-reply@xindelabs.web.id>';
const LMS_URL = String($env.NEXT_PUBLIC_LMS_URL || 'https://xindelabs-workshop.vercel.app').replace(/\/+$/, '');
const DISCORD_URL = $env.DISCORD_INVITE_URL || 'https://discord.gg/JXZWZZRsre';

const provisioned = prov.ok === true && !!prov.lms_password;
const nama = String(parsed.customerName || '').trim();
const email = String(parsed.customerEmail || prov.email || '').trim().toLowerCase();
const tierLabel = prep.tier === 'lifetime' ? 'Life-Time' : 'Tahunan';
const rupiah = (n) => 'Rp ' + Number(n || 0).toLocaleString('id-ID');

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function row(label, value, mono) {
  return '<tr><td style="padding:8px 0;color:#6b7280;font-size:14px;width:140px;vertical-align:top;">' + label + '</td>' +
    '<td style="padding:8px 0;color:#111827;font-size:14px;' +
    (mono ? 'font-family:ui-monospace,SFMono-Regular,Menlo,monospace;' : '') + '">' + value + '</td></tr>';
}

const kredensial = provisioned
  ? '<div style="margin:24px 0;padding:20px;background:#f0fdf4;border:1px solid #bbf7d0;border-radius:12px;">' +
      '<p style="margin:0 0 12px;font-weight:700;color:#065f46;font-size:16px;">\u2728 Akun Workshop lo sudah aktif</p>' +
      '<table style="width:100%;border-collapse:collapse;">' +
        row('Login', '<a href="' + LMS_URL + '/login" style="color:#047857;">' + LMS_URL + '/login</a>', true) +
        row('Email', esc(prov.email || email), true) +
        row('Password', esc(prov.lms_password), true) +
      '</table>' +
      '<p style="margin:14px 0 0;color:#065f46;font-size:13px;">Masuk pakai email + password di atas. Jangan share password ini ke siapa pun.</p>' +
    '</div>'
  : '<div style="margin:24px 0;padding:20px;background:#fef2f2;border:1px solid #fecaca;border-radius:12px;">' +
      '<p style="margin:0 0 8px;font-weight:700;color:#991b1b;font-size:16px;">Pembayaran diterima, akun sedang disiapkan</p>' +
      '<p style="margin:0;color:#7f1d1d;font-size:14px;">Sistem kami gagal membuat akses otomatis. Balas email ini supaya admin bisa mengaktifkan akun lo secara manual.</p>' +
    '</div>';

const html =
  '<div style="font-family:ui-sans-serif,system-ui,-apple-system,Segoe UI,Roboto,sans-serif;max-width:560px;margin:0 auto;padding:24px;color:#111827;">' +
  '<h1 style="font-size:20px;margin:0 0 4px;">Pembayaran diterima</h1>' +
  '<p style="margin:0 0 20px;color:#6b7280;font-size:14px;">Terima kasih' + (nama ? ', ' + esc(nama) : '') + '.</p>' +
  '<table style="width:100%;border-collapse:collapse;">' +
    row('Produk', 'Video Workshop \u2014 ' + tierLabel) +
    row('Dibayar', rupiah(parsed.amount), true) +
    row('Referensi', esc(parsed.reference || '-'), true) +
  '</table>' +
  kredensial +
  '<p style="margin:24px 0 6px;font-weight:600;font-size:15px;">Join komunitas Discord</p>' +
  '<p style="margin:0;font-size:14px;color:#4b5563;">Diskusi, sharing prompt, dan sesi use-case bareng member lain: <a href="' + DISCORD_URL + '" style="color:#047857;">' + DISCORD_URL + '</a></p>' +
  '<p style="margin:28px 0 0;color:#9ca3af;font-size:12px;">Email ini dikirim otomatis. Balas email ini kalau ada kendala.</p>' +
'</div>';

return {
  json: {
    from: RESEND_FROM,
    to: [email],
    subject: provisioned ? 'Akses Workshop Xinde Labs lo sudah aktif' : 'Pembayaran diterima \u2014 akses sedang disiapkan',
    html: html,
    lms_password: provisioned ? prov.lms_password : '',
    needs_manual: !provisioned
  }
};

// Log callback yang bukan PAID (debug)
const payment = $input.first().json;
return {
  json: {
    log: 'CALLBACK BUKAN PAID',
    status: payment.status,
    reference: payment.reference,
    amount: payment.amount
  }
};
